// Overloaded function set
void process(int value);       // Overload for integers
void process(bool value);      // Overload for booleans
void process(void* ptr);       // Overload for pointers

// Overload resolution behavior
process(0);       // Calls process(int)
// process(NULL);    // Often calls process(int), as NULL is typically 0
process(nullptr);   // Correctly calls process(void*)

// Clarity with auto
auto findResult = /* function returning a pointer */;

// if (findResult == 0) { /* Ambiguous: is findResult an int or ptr? */ }
if (findResult == nullptr) { /* Clear: findResult must be a pointer. */ }
